#define MAXV 50

int mst_weight(int V, int w[][MAXV]) {
    int used[MAXV];
    for (int i = 0; i < V; i++) used[i] = 0;
    used[0] = 1;
    int total = 0;
    for (int step = 1; step < V; step++) {
        int bu = -1, bv = -1;
        for (int u = 0; u < V; u++) {
            if (!used[u]) continue;
            for (int v = 0; v < V; v++) {
                if (used[v] || w[u][v] <= 0) continue;
                if (bu == -1 || w[u][v] < w[bu][bv]) {
                    bu = u;
                    bv = v;
                }
            }
        }
        used[bv] = 1;
        total += w[bu][bv];
    }
    return total;
}

