#define MAXV 50

int min_hops(int V, int g[][MAXV], int src, int dst) {
    int dist[MAXV];
    for (int i = 0; i < V; i++) dist[i] = -1;
    dist[src] = 0;
    int queue[MAXV];
    int qh = 0, qt = 0;
    queue[qt++] = src;
    while (qh < qt) {
        int u = queue[qh++];
        for (int v = 0; v < V; v++) {
            if (g[u][v] && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[qt++] = v;
            }
        }
    }
    return dist[dst];
}

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;
