#include <stdio.h>

#define MAXV 50

void topo_fill(int V, int g[][MAXV], int out[]) {
    int indeg[MAXV];
    for (int u = 0; u < V; u++) {
        indeg[u] = 0;
        for (int v = 0; v < V; v++) {
            if (g[v][u]) indeg[u]++;
        }
    }
    int done[MAXV];
    for (int i = 0; i < V; i++) done[i] = 0;
    for (int k = 0; k < V; k++) {
        int pick = -1;
        for (int u = 0; u < V; u++) {
            if (!done[u] && indeg[u] == 0) {
                pick = u;
                break;
            }
        }
        out[k] = pick;
        done[pick] = 1;
        for (int v = 0; v < V; v++) {
            if (g[pick][v]) indeg[v]--;
        }
    }
}

