#include <stdio.h>

#define MAXV 50

int dijkstra_dist(int V, int w[][MAXV]) {
    int dist[MAXV], used[MAXV];
    for (int i = 0; i < V; i++) {
        dist[i] = -1;
        used[i] = 0;
    }
    dist[0] = 0;
    for (int step = 0; step < V; step++) {
        int u = -1;
        for (int i = 0; i < V; i++) {
            if (!used[i] && dist[i] != -1 && (u == -1 || dist[i] < dist[u])) u = i;
        }
        if (u == -1) break;
        used[u] = 1;
        for (int v = 0; v < V; v++) {
            if (w[u][v] <= 0) continue;
            int nd = dist[u] + w[u][v];
            if (dist[v] == -1 || nd < dist[v]) dist[v] = nd;
        }
    }
    return dist[V - 1];
}

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;
    int w[MAXV][MAXV];
    for (int i = 0; i < V; i++)
