}

#include <stdio.h>

#define MAXV 50

#define MAXG 12

void sink(int R, int C, char g[][MAXG], int r, int c) {
    if (r < 0 || r >= R || c < 0 || c >= C) return;
    if (g[r][c] != '1') return;
    g[r][c] = '0';
    sink(R, C, g, r + 1, c);
    sink(R, C, g, r - 1, c);
    sink(R, C, g, r, c + 1);
    sink(R, C, g, r, c - 1);
}

int num_islands(int R, int C, char g[][MAXG]) {
    int count = 0;
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            if (g[r][c] == '1') {
                count++;
                sink(R, C, g, r, c);
            }
        }
    }
    return count;
}

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;
    char g[MAXG][MAXG];
    for (int r = 0; r < R; r++) {
        scanf("%s", g[r]);
    }
    printf("%d\n", num_islands(R, C, g));
    return 0;
}

#include <stdio.h>

#define MAXV 50

int is_bipartite(int V, int g[][MAXV]) {
    int color[MAXV];
    for (int i = 0; i < V; i++) color[i] = -1;
    for (int s = 0; s < V; s++) {
        if (color[s] != -1) continue;
        color[s] = 0;
        int queue[MAXV];
        int qh = 0, qt = 0;
        queue[qt++] = s;
        while (qh < qt) {
            int u = queue[qh++];
            for (int v = 0; v < V; v++) {
                if (!g[u][v]) continue;
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    queue[qt++] = v;
                } else if (color[v] == color[u]) {
                    return 0;
                }
            }
        }
    }
    return 1;
}

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;
    int g[MAXV][MAXV];
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++) g[i][j] = 0;
    for (int e = 0; e < E; e++) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u][v] = 1;
        g[v][u] = 1;
    }
    printf("%d\n", is_bipartite(V, g));
    return 0;
}
